export const REQUIRED_MCP_TOOLS = [
  "search_stocks",
  "get_stock_quote",
  "get_market_movers",
  "get_market_news",
];

export const GENERATED_BANNER =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
  "// To take ownership, delete this banner line; the plugin then leaves the file alone.";

export function normalizeNewlines(text) {
  return text.replace(/\r\n/g, "\n");
}

export function readDeclaredMcpVersion(packageJson) {
  return packageJson.dependencies?.["@lovable.dev/mcp-js"]
    ?? packageJson.devDependencies?.["@lovable.dev/mcp-js"]
    ?? null;
}

export function readVerifiedMcpVersion(source) {
  return source.match(/VERIFIED_MCP_JS_VERSION = "([^"]+)"/)?.[1] ?? null;
}

export function inspectMcpArtifacts({ packageJson, compatSource, manifest, bundleSource }) {
  const problems = [];
  const notes = [];
  const declared = readDeclaredMcpVersion(packageJson);
  const verified = readVerifiedMcpVersion(compatSource);
  const sdk = manifest?.sdk_version ?? null;
  if (!declared || !verified || !sdk || new Set([declared, verified, sdk]).size !== 1) {
    problems.push(
      `MCP versions disagree (package ${declared ?? "missing"}, verified emitter ${verified ?? "missing"}, manifest ${sdk ?? "missing"})`,
    );
  }
  const bundle = normalizeNewlines(bundleSource);
  if (!bundle.startsWith(GENERATED_BANNER)) {
    problems.push("generated MCP bundle is missing the AUTO-GENERATED ownership banner");
  }
  const toolNames = new Set((manifest?.mcp?.tools ?? []).map((tool) => tool.name));
  for (const tool of REQUIRED_MCP_TOOLS) {
    if (!toolNames.has(tool)) problems.push(`MCP manifest is missing tool ${tool}`);
    if (!bundle.includes(`name: "${tool}"`)) problems.push(`MCP bundle is missing tool ${tool}`);
  }
  const title = manifest?.mcp?.server?.title ?? "";
  if (!title.includes("Stocksist")) {
    problems.push(`MCP manifest title does not identify Stocksist (${title || "missing"})`);
  }
  const serverName = manifest?.mcp?.server?.name ?? "";
  if (serverName && serverName !== "Stocksist") {
    notes.push(`MCP server id is ${serverName}; public title is ${title || "unset"}`);
  }
  return { problems, notes, declared, verified, sdk };
}
